(function(){document.querySelectorAll('[id^="accordion-"] > .accordion-trigger').forEach(e=>{e.dataset.accordionBound!=="true"&&(e.dataset.accordionBound="true",e.addEventListener("click",function(){const n=this.nextElementSibling,t=this.querySelector(".icon");n.classList.contains("hidden")?(n.classList.remove("hidden"),t&&t.classList.add("rotate-180")):(n.classList.add("hidden"),t&&t.classList.remove("rotate-180"))}))})})();
